class TodoList {
    struct Task {
        int id;
        int user;
        std::string desc;
        int due;
        std::unordered_set<std::string> tags;
        bool done;
    };
    int next_id = 1;
    std::unordered_map<int, Task> tasks;
    std::unordered_map<int, std::vector<int>> user_tasks;
public:
    TodoList() {}
    int addTask(int userId, std::string taskDescription, int dueDate, std::vector<std::string> tags) {
        int tid = next_id++;
        std::unordered_set<std::string> tag_set(tags.begin(), tags.end());
        tasks[tid] = {tid, userId, taskDescription, dueDate, tag_set, false};
        user_tasks[userId].push_back(tid);
        return tid;
    }
    std::vector<std::string> getAllTasks(int userId) {
        std::vector<Task*> active;
        for (int tid : user_tasks[userId]) {
            if (!tasks[tid].done) {
                active.push_back(&tasks[tid]);
            }
        }
        std::sort(active.begin(), active.end(), [](Task* a, Task* b) {
            return a->due < b->due;
        });
        std::vector<std::string> res;
        for (auto* t : active) res.push_back(t->desc);
        return res;
    }
    std::vector<std::string> getTasksForTag(int userId, std::string tag) {
        std::vector<Task*> active;
        for (int tid : user_tasks[userId]) {
            if (!tasks[tid].done && tasks[tid].tags.count(tag)) {
                active.push_back(&tasks[tid]);
            }
        }
        std::sort(active.begin(), active.end(), [](Task* a, Task* b) {
            return a->due < b->due;
        });
        std::vector<std::string> res;
        for (auto* t : active) res.push_back(t->desc);
        return res;
    }
    void completeTask(int userId, int taskId) {
        if (tasks.count(taskId) && tasks[taskId].user == userId) {
            tasks[taskId].done = true;
        }
    }
};

class TodoList {
    static class Task {
        int id;
        int user;
        String desc;
        int due;
        java.util.Set<String> tags;
        boolean done;
        Task(int id, int user, String desc, int due, java.util.List<String> tags) {
            this.id = id;
            this.user = user;
            this.desc = desc;
            this.due = due;
            this.tags = new java.util.HashSet<>(tags);
            this.done = false;
        }
    }
    private int nextId = 1;
    private java.util.Map<Integer, Task> tasks = new java.util.HashMap<>();
    private java.util.Map<Integer, java.util.List<Integer>> userTasks = new java.util.HashMap<>();
    public TodoList() {}
    public int addTask(int userId, String taskDescription, int dueDate, java.util.List<String> tags) {
        int tid = nextId++;
        tasks.put(tid, new Task(tid, userId, taskDescription, dueDate, tags));
        userTasks.computeIfAbsent(userId, k -> new java.util.ArrayList<>()).add(tid);
        return tid;
    }
    public java.util.List<String> getAllTasks(int userId) {
        java.util.List<Task> active = new java.util.ArrayList<>();
        for (int tid : userTasks.getOrDefault(userId, java.util.Collections.emptyList())) {
            Task t = tasks.get(tid);
            if (!t.done) active.add(t);
        }
        active.sort((a, b) -> Integer.compare(a.due, b.due));
        java.util.List<String> res = new java.util.ArrayList<>();
        for (Task t : active) res.add(t.desc);
        return res;
    }
    public java.util.List<String> getTasksForTag(int userId, String tag) {
        java.util.List<Task> active = new java.util.ArrayList<>();
        for (int tid : userTasks.getOrDefault(userId, java.util.Collections.emptyList())) {
            Task t = tasks.get(tid);
            if (!t.done && t.tags.contains(tag)) active.add(t);
        }
        active.sort((a, b) -> Integer.compare(a.due, b.due));
        java.util.List<String> res = new java.util.ArrayList<>();
        for (Task t : active) res.add(t.desc);
        return res;
    }
    public void completeTask(int userId, int taskId) {
        Task t = tasks.get(taskId);
        if (t != null && t.user == userId) {
            t.done = true;
        }
    }
}

var TodoList = function() {
    this.nextId = 1;
    this.tasks = new Map();
    this.userTasks = new Map();
};
TodoList.prototype.addTask = function(userId, taskDescription, dueDate, tags) {
    const tid = this.nextId++;
    const task = {
        id: tid,
        user: userId,
        desc: taskDescription,
        due: dueDate,
        tags: new Set(tags),
        done: false
    };
    this.tasks.set(tid, task);
    if (!this.userTasks.has(userId)) {
        this.userTasks.set(userId, []);
    }
    this.userTasks.get(userId).push(tid);
    return tid;
};
TodoList.prototype.getAllTasks = function(userId) {
    const ids = this.userTasks.get(userId) || [];
    const active = [];
    for (const tid of ids) {
        const t = this.tasks.get(tid);
        if (!t.done) active.push(t);
    }
    active.sort((a, b) => a.due - b.due);
    return active.map(t => t.desc);
};
TodoList.prototype.getTasksForTag = function(userId, tag) {
    const ids = this.userTasks.get(userId) || [];
    const active = [];
    for (const tid of ids) {
        const t = this.tasks.get(tid);
        if (!t.done && t.tags.has(tag)) active.push(t);
    }
    active.sort((a, b) => a.due - b.due);
    return active.map(t => t.desc);
};
TodoList.prototype.completeTask = function(userId, taskId) {
    const t = this.tasks.get(taskId);
    if (t && t.user === userId) {
        t.done = true;
    }
};
